    async def _apply(self, edit: Edit) -> Any | None:
        """Run one edit; a toast comes back when it did not go through."""
        offer_id = await open_offer_id(self)
        if not offer_id:
            return None
        editor = MapEditor(get_asyncdb_session, offer_id, await current_user_name(self))
        try:
            await edit(editor)
        except MapConflictError as exc:
            await self._reload(offer_id)
            return rx.toast.warning(str(exc), position="top-right")
        except MapEditError as exc:
            return rx.toast.error(str(exc), position="top-right")
        except Exception:
            logger.exception("Editing the map of offer %s failed", offer_id)
            return rx.toast.error(SAVE_ERROR, position="top-right")
        await self._reload(offer_id)
        return None

    @rx.event
    def select_story(self, story_id: int) -> None:
        if str(story_id) in self.stories:
            self.selected_id = str(story_id)

    @rx.event
    def close_story(self) -> None:
        self.selected_id = ""

    @rx.event
    def set_view(self, value: str) -> None:
        if value in (VIEW_MAP, VIEW_LIST):
            self.view = value

    @rx.event
    def notify_rejected(self, count: int) -> Any:
        return _rejected_toast(count)

    @rx.event
    def toggle_slice(self, slice_id: int) -> None:
        key = str(slice_id)
        if key in self.collapsed_slices:
            self.collapsed_slices = [k for k in self.collapsed_slices if k != key]
        else:
            self.collapsed_slices = [*self.collapsed_slices, key]

    @rx.event
    def open_insert(self, edge: str) -> None:
        self.insert_at = edge

    @rx.event
    def close_insert(self) -> None:
        self.insert_at = ""

    @rx.event
    def set_map_search(self, value: str) -> None:
        self.map_search = value

    @rx.event
    def set_slice_filter(self, value: list[str]) -> None:
        self.slice_filter = value

    @rx.event
    def set_skeleton_only(self, value: bool) -> None:
        self.skeleton_only = value

    @rx.event
    def reset_filters(self) -> None:
        self.map_search = ""
        self.slice_filter = []
        self.skeleton_only = False

    @rx.event
    @requires_offer_editor
    async def load_map(self) -> AsyncGenerator[Any]:
        offer_id = await open_offer_id(self)
        if not offer_id:
            return
        try:
            await self._reload(offer_id)
        except Exception:
            logger.exception("Loading the map of offer %s failed", offer_id)
            yield rx.toast.error(LOAD_ERROR, position="top-right")

    async def _insert(self, kind: str, title: str, index: int | None) -> Any | None:
        """Add an activity or slice at ``index``; a done insert closes the popup."""
        add = MapEditor.add_activity if kind == INSERT_ACTIVITY else MapEditor.add_slice
        event = await self._apply(lambda e: add(e, self.revision, title, index))
        if event is None:
            self.insert_at = ""
        return event

    @rx.event
    @requires_offer_editor
    async def submit_insert(self, form: dict[str, Any]) -> AsyncGenerator[Any]:
        """Popup on a grid edge: kind and position come from ``insert_at``.

        The form sends only the name, because Reflex moves a form's submit
        handler out of the ``rx.foreach`` that renders the edge.
        """
        kind, _, index = self.insert_at.partition(":")
        if kind not in (INSERT_ACTIVITY, INSERT_SLICE) or not index.isdigit():
            return
        if event := await self._insert(kind, str(form.get("title", "")), int(index)):
            yield event

    @rx.event
    @requires_offer_editor
    async def add_activity(
        self, form: dict[str, Any], index: int | None = None
    ) -> AsyncGenerator[Any]:
        title = str(form.get("title", ""))
        if event := await self._insert(INSERT_ACTIVITY, title, index):
            yield event

    @rx.event
    @requires_offer_editor
    async def rename_activity(
        self, activity_id: int, title: str
    ) -> AsyncGenerator[Any]:
        # The title wraps over two lines in the header but stays one line.
        name = " ".join(title.split())
        if event := await self._apply(
            lambda e: e.rename_activity(self.revision, activity_id, name)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def move_activity(self, activity_id: int, step: int) -> AsyncGenerator[Any]:
        if event := await self._apply(
            lambda e: e.move_activity(self.revision, activity_id, step)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def archive_activity(self, activity_id: int) -> AsyncGenerator[Any]:
        if event := await self._apply(
            lambda e: e.archive_activity(self.revision, activity_id)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def add_slice(
        self, form: dict[str, Any], index: int | None = None
    ) -> AsyncGenerator[Any]:
        title = str(form.get("title", ""))
        if event := await self._insert(INSERT_SLICE, title, index):
            yield event

    @rx.event
    @requires_offer_editor
    async def rename_slice(self, slice_id: int, title: str) -> AsyncGenerator[Any]:
        if event := await self._apply(
            lambda e: e.rename_slice(self.revision, slice_id, title)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def delete_slice(self, slice_id: int) -> AsyncGenerator[Any]:
        if event := await self._apply(
            lambda e: e.delete_slice(self.revision, slice_id)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def add_story(self, form: dict[str, Any]) -> AsyncGenerator[Any]:
        """Quick add in a map cell; task and slice come as hidden form fields.

        Reflex moves a form's submit handler out of the ``rx.foreach`` that
        renders the cell, so the cell's ids travel in the form, not the call.
        """
        task_id = str(form.get("task_id", ""))
        slice_id = str(form.get("slice_id", ""))
        if not task_id.isdigit() or not int(task_id) or not slice_id.isdigit():
            yield rx.toast.error(NO_TASK, position="top-right")
            return
        title = str(form.get("title", ""))
        target = int(slice_id) or None
        if event := await self._apply(
            lambda e: e.add_story(self.revision, int(task_id), target, title)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def save_story(self, form: dict[str, Any]) -> AsyncGenerator[Any]:
        """Save the inspector form of the selected story."""
        if not self.has_selection:
            return
        story_id = int(self.selected_id)
        # Title and story parts wrap in the inspector but stay one line.
        fields = {
            name: str(value) if name == "description" else " ".join(str(value).split())
            for name, value in form.items()
        }
        before = self.revision
        if event := await self._apply(
            lambda e: e.update_story(self.revision, story_id, fields)
        ):
            yield event
        elif self.revision != before:
            yield rx.toast.success(SAVED, position="top-right")

    @rx.event
    @requires_offer_editor
    async def apply_list_changes(
        self, changes: list[dict[str, Any]]
    ) -> AsyncGenerator[Any]:
        """Save cells edited in the list; keys are ``<story id>|<column>``."""
        fields: dict[int, dict[str, str]] = {}
        rejected = 0
        for change in changes:
            story_id, _, column = str(change.get("key", "")).partition("|")
            value = str(change.get("value", ""))
            if column not in LIST_COLUMNS:
                continue
            if story_id not in self.stories:
                rejected += 1
                continue
            if column == "story":
                parts = parse_story_sentence(value)
                if parts is None:
                    rejected += 1
                    continue
                update = dict(zip(("role", "goal", "benefit"), parts, strict=True))
            else:
                update = {column: value}
            fields.setdefault(int(story_id), {}).update(update)
        if fields and (
            event := await self._apply(
                lambda e: e.update_stories(self.revision, fields)
            )
        ):
            yield event
        if rejected:
            yield _rejected_toast(rejected)

    @rx.event
    @requires_offer_editor
    async def place_story(self, task_id: str, slice_id: str) -> AsyncGenerator[Any]:
        """Move the selected story to a task and a slice (``"0"``: none)."""
        if not self.has_selection:
            return
        story_id = int(self.selected_id)
        target = int(slice_id) if slice_id and int(slice_id) != NO_SLICE_ID else None
        if event := await self._apply(
            lambda e: e.move_story(self.revision, story_id, int(task_id), target)
        ):
            yield event

    @rx.event
    @requires_offer_editor
    async def split_selected(self) -> AsyncGenerator[Any]:
        if not self.has_selection:
            return
        story_id = int(self.selected_id)
        if event := await self._apply(lambda e: e.split_story(self.revision, story_id)):
            yield event

    @rx.event
    @requires_offer_editor
    async def archive_selected(self) -> AsyncGenerator[Any]:
        if not self.has_selection:
            return
        story_id = int(self.selected_id)
        event = await self._apply(lambda e: e.archive_story(self.revision, story_id))
        if event:
            yield event
        else:
            self.selected_id = ""
"""The story map as a grid of plain values for the page (from a map snapshot)."""

from collections.abc import Collection
from typing import Any

NO_SLICE_ID = 0
NO_SLICE_TITLE = "Ohne Umsetzungsschnitt"
ORIGIN_SOURCE = "Quellenstellen"


def count_label(count: int) -> str:
    return f"{count} {'Story' if count == 1 else 'Stories'}"


def _with_count(row: dict[str, Any]) -> dict[str, Any]:
    count = sum(len(cell["stories"]) for cell in row["cells"])
    return {**row, "count_label": count_label(count)}


def _card(story: dict) -> dict[str, Any]:
    refs = len(story["source_refs"])
    return {
        "id": story["id"],
        "key": story["key"],
        "title": story["title"],
        "skeleton": story["skeleton"],
        "origin": story["origin"],
        "sentence": story["sentence"],
        "description": story.get("description", ""),
        "refs": f"{refs} {ORIGIN_SOURCE}" if refs else "ohne Quellenbezug",
    }


def build_view(snapshot: dict) -> dict[str, Any]:
    """Columns, slice rows, option lists and a story lookup for the editor."""
    activities = [a for a in snapshot["activities"] if not a["archived"]]
    slices = snapshot["slices"]
    tasks_of = {
        a["id"]: [t for t in a["tasks"] if not t["archived"]] for a in activities
    }
    columns = [
        {
            "id": a["id"],
            "index": index,
            "title": a["title"],
            "tasks": " · ".join(t["title"] for t in tasks_of[a["id"]]),
            "task_id": tasks_of[a["id"]][0]["id"] if tasks_of[a["id"]] else 0,
            "first": index == 0,
            "last": index == len(activities) - 1,
        }
        for index, a in enumerate(activities)
    ]

    def cell(activity: dict, slice_id: int) -> dict[str, Any]:
        stories = [
            _card(s)
            for t in tasks_of[activity["id"]]
            for s in t["stories"]
            if not s["archived"] and (s["slice_id"] or NO_SLICE_ID) == slice_id
        ]
        first_task = (
            tasks_of[activity["id"]][0]["id"] if tasks_of[activity["id"]] else 0
        )
        return {
            "activity_id": activity["id"],
            "task_id": first_task,
            "stories": stories,
        }

    row_defs = [(s["id"], s["title"], True) for s in slices] + [
        (NO_SLICE_ID, NO_SLICE_TITLE, False)
    ]
    rows = [
        _with_count(
            {
                "slice_id": slice_id,
                # A new slice inserted at this row's top edge gets this index.
                "index": index,
                "title": title,
                "editable": editable,
                "cells": [cell(a, slice_id) for a in activities],
            }
        )
        for index, (slice_id, title, editable) in enumerate(row_defs)
    ]
    lookup = {
        str(story["id"]): {
            **_card(story),
            "role": story["role"],
            "goal": story["goal"],
            "benefit": story["benefit"],
            "task_id": str(task["id"]),
            "slice_id": str(story["slice_id"] or NO_SLICE_ID),
        }
        for activity in activities
        for task in tasks_of[activity["id"]]
        for story in task["stories"]
        if not story["archived"]
    }
    return {
        "columns": columns,
        "rows": rows,
        "stories": lookup,
        "story_count": len(lookup),
        "task_options": [
            {"value": str(t["id"]), "label": f"{a['title']} · {t['title']}"}
            for a in activities
            for t in tasks_of[a["id"]]
        ],
        "slice_options": [{"value": str(NO_SLICE_ID), "label": NO_SLICE_TITLE}]
        + [{"value": str(s["id"]), "label": s["title"]} for s in slices],
    }


def filter_rows(
    rows: list[dict[str, Any]],
    *,
    search: str = "",
    slice_ids: Collection[str] = (),
    skeleton_only: bool = False,
) -> list[dict[str, Any]]:
    """Rows of the chosen slices with only the stories matching every filter."""
    needle = search.strip().casefold()

    def keep(story: dict[str, Any]) -> bool:
        text = f"{story['key']} {story['title']}".casefold()
        return (not skeleton_only or story["skeleton"]) and needle in text

    return [
        _with_count(
            {
                **row,
                "cells": [
                    {**cell, "stories": [s for s in cell["stories"] if keep(s)]}
                    for cell in row["cells"]
                ],
            }
        )
        for row in rows
        if not slice_ids or str(row["slice_id"]) in slice_ids
    ]


def list_rows(
    columns: list[dict[str, Any]], rows: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Stories as list lines: by activity, then slice, then their map order."""
    return [
        {
            "id": story["id"],
            "key": story["key"],
            "activity": column["title"],
            "title": story["title"],
            "story": story["sentence"],
            "description": story["description"],
        }
        for index, column in enumerate(columns)
        for row in rows
        for story in row["cells"][index]["stories"]
    ]
        StatementEntity(
            offer_id=offer_id,
            type=type_,
            text=text,
            source_refs=refs,
            # An evidence claim without evidence needs a second look.
            needs_recheck=type_ in EVIDENCE_TYPES and not refs,
        )
    )


async def snapshot_map(session: AsyncSession, workspace: WorkspaceEntity) -> dict:
    """Immutable JSON of the map as it stands; stories carry their sentence."""
    offer_id = workspace.offer_id

    async def _rows[T](entity: type[T], position: object) -> list[T]:
        statement = select(entity).where(
            getattr(entity, "offer_id") == offer_id  # noqa: B009
        )
        ordered = statement.order_by(position, getattr(entity, "id"))  # noqa: B009  # ty: ignore[invalid-argument-type]
        return list((await session.scalars(ordered)).all())

    activities = await _rows(ActivityEntity, ActivityEntity.position)
    tasks = await _rows(TaskEntity, TaskEntity.position)
    stories = await _rows(StoryEntity, StoryEntity.position)
    slices = await _rows(SliceEntity, SliceEntity.position)
    return {
        "vision": workspace.vision,
        "roles": list(workspace.roles),
        "slices": [{"id": s.id, "title": s.title} for s in slices],
        "activities": [
            {
                "id": a.id,
                "title": a.title,
                "archived": a.archived_at is not None,
                "tasks": [
                    {
                        "id": t.id,
                        "title": t.title,
                        "archived": t.archived_at is not None,
                        "stories": [
                            _story_dict(s) for s in stories if s.task_id == t.id
                        ],
                    }
                    for t in tasks
                    if t.activity_id == a.id
                ],
            }
            for a in activities
        ],
        "unassigned": [_story_dict(s) for s in stories if s.task_id is None],
    }


def _story_dict(story: StoryEntity) -> dict:
    return {
        "id": story.id,
        "key": story.key,
        "title": story.title,
        "role": story.role,
        "goal": story.goal,
        "benefit": story.benefit,
        "sentence": story_sentence(story.role, story.goal, story.benefit),
        "description": story.description,
        "origin": story.origin,
        "slice_id": story.slice_id,
        "skeleton": story.skeleton,
        "source_refs": story.source_refs,
        "archived": story.archived_at is not None,
    }

