/* Layout rules for alloq components. Colors and the Mantine theme live in
   alloq_commons/theme.py (GLOBAL_CSS, --aq-* tokens). */

/* ===== Planning views on the white content pane ===== */
#planning-grid-root,
#project-view-root {
    background-color: var(--aq-surface) !important;
}

/* ===== Unified Modal & Drawer styling ===== */
.alloq-modal.mantine-Modal-content,
.alloq-modal .mantine-Modal-content,
.alloq-drawer.mantine-Drawer-content,
.alloq-drawer .mantine-Drawer-content,
.alloq-employee-detail-drawer.mantine-Drawer-content,
.alloq-employee-detail-drawer .mantine-Drawer-content,
.alloq-project-detail-drawer.mantine-Drawer-content,
.alloq-project-detail-drawer .mantine-Drawer-content,
.alloq-employee-detail-modal.mantine-Modal-content,
.alloq-employee-detail-modal .mantine-Modal-content,
.alloq-project-detail-modal.mantine-Modal-content,
.alloq-project-detail-modal .mantine-Modal-content {
    background-color: var(--alloq-surface-muted);
    border: 1px solid var(--alloq-border);
    overflow: hidden;
}

.alloq-modal .mantine-Modal-header,
.alloq-drawer .mantine-Drawer-header,
.alloq-employee-detail-drawer .mantine-Drawer-header,
.alloq-project-detail-drawer .mantine-Drawer-header,
.alloq-employee-detail-modal .mantine-Modal-header,
.alloq-project-detail-modal .mantine-Modal-header {
    background-color: var(--alloq-surface-muted);
    padding-left: 36px;
    border-bottom: none !important;
    box-shadow: none !important;
}

.alloq-modal .mantine-Modal-title,
.alloq-drawer .mantine-Drawer-title,
.alloq-employee-detail-drawer .mantine-Drawer-title,
.alloq-project-detail-drawer .mantine-Drawer-title {
    font-weight: bold;
    font-size: 1.2rem;
}

.alloq-modal .mantine-Modal-close,
.alloq-drawer .mantine-Drawer-close,
.alloq-employee-detail-drawer .mantine-Drawer-close,
.alloq-project-detail-drawer .mantine-Drawer-close,
.alloq-employee-detail-modal .mantine-Modal-close,
.alloq-project-detail-modal .mantine-Modal-close {
    border: none !important;
    outline: none !important;
}

.alloq-modal .mantine-Modal-body,
.alloq-drawer .mantine-Drawer-body,
.alloq-employee-detail-drawer .mantine-Drawer-body,
.alloq-project-detail-drawer .mantine-Drawer-body,
.alloq-employee-detail-modal .mantine-Modal-body,
.alloq-project-detail-modal .mantine-Modal-body {
    background-color: var(--alloq-surface-muted);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 0;
}

.alloq-drawer .mantine-Drawer-body,
.alloq-employee-detail-drawer .mantine-Drawer-body,
.alloq-project-detail-drawer .mantine-Drawer-body {
    height: calc(100dvh - var(--drawer-offset) * 2 - 60px);
}

.alloq-modal .mantine-Modal-body,
.alloq-employee-detail-modal .mantine-Modal-body,
.alloq-project-detail-modal .mantine-Modal-body {
    max-height: calc(100dvh - 200px);


def _source_row(source: ObjectVar[dict[str, Any]]) -> rx.Component:
    """Name and actions in one line; the status below uses the full card width."""
    return mn.stack(
        _source_head(source),
        mn.text(
            source["summary"],
            fz="12px",
            c=rx.cond(source["ok"], theme.POSITIVE, theme.WARNING),
            # Starts under the name, not under the checkbox.
            pl=CHECKBOX_PX + HEAD_GAP_PX,
        ),
        gap=6,
        p=10,
        style={"borderRadius": "8px", "background": theme.SURFACE_MUTED},
    )


def _source_head(source: ObjectVar[dict[str, Any]]) -> rx.Component:
    return mn.group(
        mn.checkbox(
            checked=source["included"],
            disabled=~source["usable"],
            size=CHECKBOX_SIZE,
            on_change=lambda checked: SourcesState.toggle_source(  # ty: ignore[invalid-argument-type]
                source["id"], checked
            ),
        ),
        mn.text(
            source["name"],
            fw=600,
            fz="13px",
            style={"minWidth": "0", "flex": "1", "overflowWrap": "anywhere"},
        ),
        mn.action_icon(
            rx.icon("eye", size=16),
            variant="subtle",
            color="gray",
            size="sm",
            on_click=SourcesState.open_viewer(source["id"]),
            aria_label=VIEW_LABEL,
            custom_attrs={"title": VIEW_LABEL},
        ),
        rx.cond(
            source["retryable"],
            mn.button(
                RETRY_LABEL,
                variant="subtle",
                size="compact-xs",
                on_click=SourcesState.retry_source(source["id"]),
"""Shared modal/drawer layout primitives.

Provides consistent structure, sticky footer, and CSS-class-driven theming
so that all modals and drawers share the same visual language.
"""

from typing import Any

import reflex as rx
from reflex.event import EventType

import appkit_mantine as mn

# CSS class applied to mn.modal / mn.drawer for unified styling.
MODAL_CLASS = "alloq-modal"
DRAWER_CLASS = "alloq-drawer"


def modal_footer(
    submit_label: str,
    on_cancel: EventType[()],
    *,
    disabled: bool | rx.Var[bool] = False,
    loading: bool | rx.Var[bool] = False,
) -> rx.Component:
    """Sticky footer with cancel + submit buttons for modals/drawers."""
    return mn.group(
        mn.button(
            "Abbrechen",
            variant="subtle",
            on_click=on_cancel,
        ),
        mn.button(
            submit_label,
            type="submit",
            disabled=disabled,
            loading=loading,
            px="xl",
        ),
        justify="end",
        class_name="alloq-modal-footer",
    )


def modal_form_layout(
    content: rx.Component,
    footer: rx.Component,
    on_submit: EventType[Any],
    *,
    reset_on_submit: bool = False,
) -> rx.Component:
    """Form layout with scrollable body and fixed footer.

